/**
 * TypeScript Function Node for Node-RED
 * Dedicated TypeScript function node with full type support
 */

module.exports = function(RED) {
    "use strict";
    var util = require("util");
    var vm = require("vm");
    var path = require("path");
    var fs = require("fs-extra");
    
    // Import TypeScript compiler service
    var TypeScriptCompiler = require("../../../runtime/lib/typescript-compiler");
    
    function sendResults(node, send, _msgid, msgs, cloneFirstMessage) {
        if (msgs == null) {
            return;
        } else if (!util.isArray(msgs)) {
            msgs = [msgs];
        }
        var msgCount = 0;
        for (var m = 0; m < msgs.length; m++) {
            if (msgs[m]) {
                if (!util.isArray(msgs[m])) {
                    msgs[m] = [msgs[m]];
                }
                for (var n = 0; n < msgs[m].length; n++) {
                    var msg = msgs[m][n];
                    if (msg !== null && msg !== undefined) {
                        if (typeof msg === 'object' && !Buffer.isBuffer(msg) && !util.isArray(msg)) {
                            if (msgCount === 0 && cloneFirstMessage !== false) {
                                msgs[m][n] = RED.util.cloneMessage(msgs[m][n]);
                                msg = msgs[m][n];
                            }
                            msg._msgid = _msgid;
                        }
                        msgCount++;
                    }
                }
            }
        }
        if (msgCount > 0) {
            send(msgs);
        }
    }

    function TypeScriptFunctionNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.name = n.name;
        node.func = n.func;
        node.compiledFunc = n.compiledFunc;
        node.compilationErrors = n.compilationErrors || [];
        node.outputs = n.outputs;
        node.libs = n.libs || [];
        
        var handleNodeDoneCall = true;

        // Check if we have pre-compiled code
        if (!node.compiledFunc) {
            if (node.compilationErrors && node.compilationErrors.length > 0) {
                node.status({fill: "red", shape: "ring", text: "Compilation errors"});
                const errorSummary = node.compilationErrors.map(e => 
                    `Line ${e.line}: ${e.message}`
                ).join('; ');
                node.error("TypeScript compilation failed: " + errorSummary);
            } else {
                node.status({fill: "red", shape: "ring", text: "No compiled code"});
                node.error("No compiled TypeScript code found. Please edit and deploy the node.");
            }
            return;
        }
        
        if (node.compilationErrors && node.compilationErrors.length > 0) {
            node.status({fill: "yellow", shape: "ring", text: "Compilation warnings"});
            node.warn("TypeScript compilation had warnings: " + node.compilationErrors.map(e => e.message).join('; '));
        } else {
            node.status({fill: "green", shape: "dot", text: "Ready"});
        }

        var nodeContext = {
            id: node.id,
            name: node.name,
            outputCount: node.outputs,
            log: function() {
                node.log.apply(node, arguments);
            },
            error: function() {
                node.error.apply(node, arguments);
            },
            warn: function() {
                node.warn.apply(node, arguments);
            },
            debug: function() {
                node.debug.apply(node, arguments);
            },
            trace: function() {
                node.trace.apply(node, arguments);
            },
            send: function(msgs, cloneFirstMessage) {
                // We'll override this in the actual message processing
                console.warn('[TS-Function] nodeContext.send called - this should be overridden');
            },
            done: function(err) {
                // We'll override this in the actual message processing
                console.warn('[TS-Function] nodeContext.done called - this should be overridden');
            },
            status: function() {
                node.status.apply(node, arguments);
            },
            context: {
                set: function() {
                    node.context().set.apply(node, arguments);
                },
                get: function() {
                    return node.context().get.apply(node, arguments);
                },
                keys: function() {
                    return node.context().keys.apply(node, arguments);
                },
                get global() {
                    return node.context().global;
                },
                get flow() {
                    return node.context().flow;
                }
            },
            flow: {
                set: function() {
                    node.context().flow.set.apply(node, arguments);
                },
                get: function() {
                    return node.context().flow.get.apply(node, arguments);
                },
                keys: function() {
                    return node.context().flow.keys.apply(node, arguments);
                }
            },
            global: {
                set: function() {
                    node.context().global.set.apply(node, arguments);
                },
                get: function() {
                    return node.context().global.get.apply(node, arguments);
                },
                keys: function() {
                    return node.context().global.keys.apply(node, arguments);
                }
            },
            env: {
                get: function(envVar) {
                    return RED.util.getSetting(node, envVar);
                }
            },
            require: null,
            // Custom require for userDir imports
            requireUserDir: function(modulePath) {
                const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
                
                // Try different extensions
                const extensions = ['.js', '.ts', '.tsx', ''];
                let foundPath = null;
                
                for (const ext of extensions) {
                    const testPath = path.resolve(userDir, modulePath + ext);
                    if (fs.existsSync(testPath)) {
                        foundPath = testPath;
                        break;
                    }
                }
                
                if (!foundPath) {
                    throw new Error(`Failed to require userDir module '${modulePath}': Module not found`);
                }
                
                try {
                    // If it's a TypeScript file, compile it first
                    if (foundPath.endsWith('.ts') || foundPath.endsWith('.tsx')) {
                        const tsContent = fs.readFileSync(foundPath, 'utf8');
                        
                        // Synchronous compilation for simple cases
                        const ts = require('typescript');
                        const result = ts.transpileModule(tsContent, {
                            compilerOptions: {
                                target: ts.ScriptTarget.ES2020,
                                module: ts.ModuleKind.CommonJS,
                                esModuleInterop: true,
                                allowSyntheticDefaultImports: true,
                                skipLibCheck: true
                            }
                        });
                        
                        // Execute compiled JavaScript in a module context
                        const Module = require('module');
                        const compiledModule = new Module(foundPath, module);
                        compiledModule.filename = foundPath;
                        compiledModule.paths = Module._nodeModulePaths(path.dirname(foundPath));
                        
                        // Create require function for the compiled module
                        const compiledRequire = Module.createRequire(foundPath);
                        
                        // Execute the compiled code
                        const compiledFunction = new Function('require', 'module', 'exports', '__filename', '__dirname', result.outputText);
                        compiledFunction.call(
                            compiledModule.exports,
                            compiledRequire,
                            compiledModule,
                            compiledModule.exports,
                            foundPath,
                            path.dirname(foundPath)
                        );
                        
                        return compiledModule.exports;
                    } else {
                        // Regular JavaScript file
                        if (require.cache[foundPath]) {
                            delete require.cache[foundPath];
                        }
                        return require(foundPath);
                    }
                } catch (err) {
                    throw new Error(`Failed to require userDir module '${modulePath}': ${err.message}`);
                }
            }
        };

        var node_require = null;
        var nodeRequire = function(module) {
            if (!node_require) {
                node_require = require("module").createRequire(require('url').pathToFileURL(__filename));
            }
            return node_require(module);
        }
        nodeContext.require = nodeRequire;

        var compiledCode = node.compiledFunc;
        
        console.log('[TS-Function] Using pre-compiled TypeScript code:');
        console.log('--- START COMPILED CODE ---');
        console.log(compiledCode);
        console.log('--- END COMPILED CODE ---');

        // Setup the compiled function execution context
        (function() {

            try {
                var customRequire = function(moduleName) {
                    // Handle userDir imports
                    if (moduleName.startsWith('@userDir/')) {
                        const userDirPath = moduleName.replace('@userDir/', '');
                        return nodeContext.requireUserDir(userDirPath);
                    }
                    // Standard require
                    return nodeRequire(moduleName);
                };

                var functionHeader = `
                    var __node__ = {
                        id: nodeContext.id,
                        name: nodeContext.name,
                        outputCount: nodeContext.outputCount,
                        log: nodeContext.log,
                        error: nodeContext.error,
                        warn: nodeContext.warn,
                        debug: nodeContext.debug,
                        trace: nodeContext.trace,
                        send: nodeContext.send,
                        done: nodeContext.done,
                        status: nodeContext.status
                    };
                    var node = __node__;
                    var context = nodeContext.context;
                    var flow = nodeContext.flow;
                    var global = nodeContext.global;
                    var env = nodeContext.env;
                    var require = ${customRequire.toString()};
                    var requireUserDir = nodeContext.requireUserDir;
                    var RED = { util: RED.util };
                    var __send__ = function(msgs, cloneMsg) {
                        // This will be properly bound in processMessage
                        console.warn('[TS-Function] __send__ called from header context');
                    };
                    var __done__ = function(err) {
                        // This will be properly bound in processMessage  
                        console.warn('[TS-Function] __done__ called from header context');
                    };
                `;

                var functionFooter = `
                    // Execute compiled TypeScript code and store result
                    var __functionResult = null;
                    var __functionError = null;
                    var __functionCompleted = false;
                    
                    try {
                        // Create module context for TypeScript exports
                        var module = { exports: {} };
                        var exports = module.exports;
                        
                        ${compiledCode}
                        
                        // Handle different export patterns
                        let userFunction;
                        if (typeof module.exports === 'function') {
                            // export default function or module.exports = function
                            userFunction = module.exports;
                        } else if (module.exports.default && typeof module.exports.default === 'function') {
                            // export default function
                            userFunction = module.exports.default;
                        } else if (typeof exports === 'function') {
                            // exports = function
                            userFunction = exports;
                        } else {
                            // No exported function found - error
                            throw new Error('No exported function found. Please use "export default function" or "module.exports = function".');
                        }
                        
                        // Call the exported function with Node-RED context
                        console.log('[TS-Function] Calling user function...');
                        __functionResult = userFunction(__msg__, __send__, __done__, node, context, flow, global, env);
                        console.log('[TS-Function] User function returned:', typeof __functionResult, __functionResult ? 'with payload:' : 'null/undefined', __functionResult?.payload);
                        __functionCompleted = true;
                        
                    } catch (error) {
                        console.error('[TS-Function] Function execution error:', error);
                        __functionError = error;
                        __functionCompleted = true;
                    }
                `;

                var fullFunctionText = functionHeader + functionFooter;

                var scriptOpt = {
                    filename: 'TypeScript Function node:' + node.name + ' [' + node.id + ']',
                    displayErrors: true
                };

                var vmScript = new vm.Script(fullFunctionText, scriptOpt);
                var sandbox = {
                    nodeContext: nodeContext,
                    RED: RED,
                    __node__: {
                        id: node.id,
                        name: node.name,
                        outputCount: node.outputs,
                        log: function() {
                            node.log.apply(node, arguments);
                        },
                        error: function() {
                            node.error.apply(node, arguments);
                        },
                        warn: function() {
                            node.warn.apply(node, arguments);
                        },
                        debug: function() {
                            node.debug.apply(node, arguments);
                        },
                        trace: function() {
                            node.trace.apply(node, arguments);
                        },
                        send: function(id, msgs, cloneMsg) {
                            sendResults(node, node.send, id, msgs, cloneMsg);
                        },
                        done: function() {
                            if (handleNodeDoneCall) {
                                node.done.apply(node, arguments);
                            }
                        },
                        status: function() {
                            node.status.apply(node, arguments);
                        }
                    },
                    context: nodeContext.context,
                    flow: nodeContext.flow,
                    global: nodeContext.global,
                    env: nodeContext.env,
                    require: customRequire,
                    requireUserDir: nodeContext.requireUserDir,
                    // Add module context for CommonJS compiled TypeScript
                    exports: {},
                    module: { exports: {} },
                    // Add placeholder context variables that will be set at runtime
                    __msg__: null,
                    __msgid__: null,
                    __send__: null,
                    __done__: null,
                    // Add result variables
                    __functionResult: null,
                    __functionError: null,
                    __functionCompleted: false,
                    setTimeout: setTimeout,
                    clearTimeout: clearTimeout,
                    setInterval: setInterval,
                    clearInterval: clearInterval,
                    setImmediate: setImmediate,
                    clearImmediate: clearImmediate,
                    process: {
                        env: process.env,
                        version: process.version,
                        versions: process.versions,
                        platform: process.platform,
                        arch: process.arch
                    },
                    Buffer: Buffer,
                    Date: Date,
                    console: console,
                    util: util
                };

                if (util.hasOwnProperty('promisify')) {
                    sandbox.util.promisify = util.promisify;
                }

                const RESOLVING = 0;
                const RESOLVED = 1;
                const ERROR = 2;
                var state = RESOLVING;
                var messages = [];

                var processMessage = (() => {});

                node.on("input", function(msg, send, done) {
                    if (state === RESOLVING) {
                        messages.push({msg: msg, send: send, done: done});
                    } else if (state === RESOLVED) {
                        processMessage(msg, send, done);
                    }
                });

                // Wait for any async setup to complete
                const context = vm.createContext(sandbox);
                processMessage = function(msg, send, done) {
                    handleNodeDoneCall = true;
                    
                    try {
                        var start = process.hrtime();
                        
                        // Create properly bound send and done functions
                        var boundSend = function(msgs) {
                            if (msgs === null || msgs === undefined) {
                                return; // Don't send anything
                            }
                            sendResults(node, send, msg._msgid, msgs, false);
                        };
                        
                        var boundDone = function(err) {
                            if (done && typeof done === 'function') {
                                done(err);
                            }
                        };
                        
                        // Override the context functions with properly bound ones
                        context.nodeContext.send = boundSend;
                        context.nodeContext.done = boundDone;
                        
                        // Set runtime context variables
                        context.__msg__ = msg;
                        context.__msgid__ = msg._msgid;
                        context.__send__ = boundSend;
                        context.__done__ = boundDone;
                        
                        console.log('[TS-Function] Executing compiled TypeScript function...');
                        console.log('[TS-Function] Message ID:', msg._msgid);
                        
                        vmScript.runInContext(context);
                        
                        // Check the function execution result
                        var functionResult = context.__functionResult;
                        var functionError = context.__functionError;
                        var functionCompleted = context.__functionCompleted;
                        
                        console.log('[TS-Function] Function completed:', functionCompleted);
                        console.log('[TS-Function] Function error:', functionError);
                        console.log('[TS-Function] Function result:', typeof functionResult, functionResult?.payload);
                        
                        if (functionError) {
                            console.error('[TS-Function] Function execution error:', functionError);
                            node.error('Function execution error: ' + functionError.message, msg);
                            boundDone(functionError);
                        } else if (functionCompleted) {
                            // Handle the result
                            if (functionResult !== undefined) {
                                if (functionResult === null) {
                                    console.log('[TS-Function] Result is null, not sending message');
                                    // null means don't send anything
                                    boundDone();
                                } else {
                                    console.log('[TS-Function] Sending result to next node');
                                    // Send the result
                                    boundSend(functionResult);
                                    boundDone();
                                }
                            } else {
                                console.log('[TS-Function] Result is undefined, not sending message');
                                // If result is undefined, don't send anything
                                boundDone();
                            }
                        } else {
                            console.error('[TS-Function] Function did not complete properly');
                            node.error('Function did not complete properly', msg);
                            boundDone(new Error('Function did not complete'));
                        }
                        
                        var duration = process.hrtime(start);
                        var converted = Math.floor((duration[0] * 1e9 + duration[1]) / 10000) / 100;
                        node.metric("duration", msg, converted);
                        if (process.env.NODE_RED_FUNCTION_TIME) {
                            node.log("TypeScript function completed in " + converted + "ms");
                        }
                    } catch (err) {
                        console.error('[TS-Function] Runtime error:', err);
                        console.error('[TS-Function] Error stack:', err.stack);
                        node.error(`TypeScript function runtime error: ${err.message}`, msg);
                        if (done && typeof done === 'function') {
                            done(err);
                        }
                    }
                };

                state = RESOLVED;

                // Process any buffered messages
                messages.forEach(function(m) {
                    processMessage(m.msg, m.send, m.done);
                });
                messages = null;

                node.status({fill: "green", shape: "dot", text: "ready"});

            } catch (err) {
                state = ERROR;
                node.error(err);
                node.status({fill: "red", shape: "ring", text: "error"});
            }
        })(); // Close the IIFE

        node.on("close", function() {
            node.status({});
        });
    }
    
    RED.nodes.registerType("typescript-function", TypeScriptFunctionNode);
}; 